from dataclasses import dataclass

@dataclass(frozen=True)
class Line:
    sku: str
    unit_cents: int
    quantity: int

def quote(lines, region):
    if region not in {'domestic', 'international'}:
        raise ValueError('region')
    subtotal = 0
    for line in lines:
        if line.unit_cents < 0 or line.quantity < 1:
            raise ValueError('line')
        subtotal += line.unit_cents * line.quantity
    shipping = 0 if subtotal == 0 else (700 if region == 'domestic' else 2000)
