from dataclasses import dataclass

@dataclass(frozen=True)
class Line:
    sku: str
    unit_cents: int
    quantity: int

def quote(lines, region, member=False):
    if region not in {'domestic', 'international'}:
        raise ValueError('region')
    subtotal = 0
    has_lines = False
    for line in lines:
        if line.unit_cents < 0 or line.quantity < 1:
            raise ValueError('line')
        has_lines = True
        subtotal += line.unit_cents * line.quantity
    discount = subtotal // 10 if member and subtotal >= 5000 else 0
    merchandise = subtotal - discount
    if not has_lines:
        shipping = 0
    elif region == 'international':
        shipping = 2000
    else:
        shipping = 0 if merchandise >= 5000 else 700
    return {
        'subtotal_cents': subtotal,
        'discount_cents': discount,
        'shipping_cents': shipping,
        'total_cents': merchandise + shipping,
    }
